create table if not exists public.transactions (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,description text not null,amount numeric not null check(amount>0),type text not null check(type in ('income','expense')),category text not null default 'Outros',date date not null,created_at timestamptz not null default now());
create table if not exists public.goals (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_amount numeric not null check(target_amount>0),saved_amount numeric not null default 0,due_date date);
create table if not exists public.commitments (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null,kind text not null check(kind in ('bill','debt')),amount numeric not null check(amount>0),due_date date not null,installments_total integer,installments_paid integer default 0,status text not null default 'pending' check(status in ('pending','paid')));
create table if not exists public.driver_days (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,date date not null,gross_earnings numeric not null default 0,rides integer not null default 0,hours_worked numeric not null default 0,odometer_start numeric not null default 0,odometer_end numeric not null default 0,kilometers numeric not null default 0,fuel_cost numeric not null default 0,maintenance_cost numeric not null default 0,other_cost numeric not null default 0,notes text not null default '',created_at timestamptz not null default now());
create table if not exists public.credit_cards (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null,last_four text not null default '0000',color text not null default 'blue',credit_limit numeric not null check(credit_limit>0),closing_day integer not null default 1,due_day integer not null default 10);
create table if not exists public.card_purchases (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,card_id bigint not null references public.credit_cards(id) on delete cascade,description text not null,total_amount numeric not null check(total_amount>0),installments integer not null default 1,purchase_date date not null,category text not null default 'Outros',created_at timestamptz not null default now());
create index if not exists idx_transactions_user_date on public.transactions(user_id,date desc);create index if not exists idx_goals_user on public.goals(user_id);create index if not exists idx_commitments_user_due on public.commitments(user_id,due_date);create index if not exists idx_driver_days_user_date on public.driver_days(user_id,date desc);create index if not exists idx_credit_cards_user on public.credit_cards(user_id);create index if not exists idx_card_purchases_user_card on public.card_purchases(user_id,card_id);
alter table public.transactions enable row level security;alter table public.goals enable row level security;alter table public.commitments enable row level security;alter table public.driver_days enable row level security;alter table public.credit_cards enable row level security;alter table public.card_purchases enable row level security;
do $$ declare t text; begin foreach t in array array['transactions','goals','commitments','driver_days','credit_cards','card_purchases'] loop execute format('drop policy if exists "Usuários gerenciam os próprios dados" on public.%I',t);execute format('create policy "Usuários gerenciam os próprios dados" on public.%I for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id)',t);end loop;end $$;
